  'admin.schoolFeatureUsage.loadError': 'အင်္ဂါရပ်အသုံးပြုမှုကို ဖွင့်ခြင်း မအောင်မြင်ပါ။',
  'admin.schoolFeatureUsage.nameSep': ', ',
  'admin.schoolFeatureUsage.noneListed': 'မရှိ',
  'admin.schoolFeatureUsage.bottleneckNone': 'ယခုနှစ် လုပ်ငန်းစဥ်တစ်ခုစီ၏ ဖြတ်သန်းနှုန်းသည် အလုံးစုံတည်ငြိမ်နေပြီး LLM တုံ့ပြန်မှုသည် သိသိသာသာနှေးကွေးသည်မဟုတ်ပါ (၎င်းသည် ပျမ်းမျှထက်ပိုမိုမြင့်မားပြီး ဤ module ၏အဆင့်ကိုရောက်ရှိစေရမည်- ပတ္တူအတွက် 8 စက္ကန့်နှင့် ဆွေးနွေးပွဲအတွက် 90 စက္ကန့်)။ လုပ်ငန်းစဉ်ဖြတ်သန်းမှုနှုန်းသည် လုပ်ဆောင်ချက်ဆိုင်ရာဖြစ်ရပ်များမှ လာပြီး LLM ကျရှုံးမှုနှုန်းသည် တိုကင်အသုံးပြုမှုမှ လာသည်။',
  'admin.schoolFeatureUsage.bottleneckVolume': 'လုပ်ငန်းစဉ်တစ်ခုစီ၏ ဖြတ်သန်းနှုန်းသည် ယေဘုယျအားဖြင့် မြင့်မားသည်။ လက်ရှိကန့်သတ်ချက်များသည် အဓိကအားဖြင့် အသုံးပြုမှုဖြန့်ဖြူးခြင်းနှင့် idle modules ({idle}) မှ ချို့ယွင်းချက်များအား လုပ်ဆောင်ခြင်း သို့မဟုတ် နှေးကွေးခြင်းထက် လုပ်ဆောင်ခြင်းဖြစ်သည်။',
  'admin.schoolFeatureUsage.bottleneckSlow': 'ဖြတ်သန်းနှုန်းသည် အလုံးစုံတည်ငြိမ်သည်။ LLM ဆိုသည်မှာ ဤ module အတွက် သတ်မှတ်ချက်များနှင့် ပြည့်မီသော အလယ်အလတ်အထက် တုံ့ပြန်မှုဆိုသည်မှာ {slow} ဖြစ်သည်။',
  'admin.schoolFeatureUsage.bottleneckPass': 'နိမ့်သောဖြတ်သန်းနှုန်းဖြင့် လုပ်ငန်းစဉ်သည် {lowest}; တင်းကျပ်သောဝန်အကဲဖြတ်ခြင်းလုပ်ငန်းစဉ်သည် {tense} ဖြစ်သည်။ ဖြတ်သန်းမှုနှုန်းသည် လုပ်ဆောင်ချက်ဆိုင်ရာ ဖြစ်ရပ်များမှ လာသည်၊ ကျေးဇူးပြု၍ အသုံးပြုမှုအပေါ် အခြေခံ၍ ၎င်းကို ဘာသာပြန်ပေးပါ။',
  'admin.schoolFeatureUsage.bottleneckPassSlow': 'နိမ့်သောဖြတ်သန်းနှုန်းဖြင့် လုပ်ငန်းစဉ်သည် {lowest}; တင်းကျပ်သည့်အတိုင်း ဝန်အကဲဖြတ်ခြင်းနှင့် လုပ်ငန်းစဉ်သည် {tense}; နှေးကွေးသော LLM တုံ့ပြန်မှုဖြင့် လုပ်ငန်းစဉ်သည် (ပျမ်းမျှအားဖြင့် အလယ်အလတ်ထက်နှင့် မော်ဂျူးအဆင့်သတ်မှတ်ချက်သို့ရောက်ရှိခြင်း) သည် {slow} ဖြစ်သည်။',
