  'admin.schoolFeatureUsage.usageRateHint': 'လွှမ်းခြုံ = နှစ်စဉ်လာရောက်သူအရေအတွက် / လက်ရှိကျောင်းသားဦးရေ။',
  'admin.schoolFeatureUsage.highTitle': '2. မြင့်မားသောကြိမ်နှုန်းလုပ်ဆောင်ချက်စာရင်း',
  'admin.schoolFeatureUsage.lowIdleTitle': '3. ကြိမ်နှုန်းနည်းပြီး ရေရှည်မလှုပ်မရှားလုပ်ဆောင်မှုများစာရင်း',
  'admin.schoolFeatureUsage.lowIdleBody': 'ကြိမ်နှုန်းနိမ့်- {low}။ ရေရှည် ရပ်နားခြင်း- {idle}။ အသုံးမပြုသောအချက်အလက်များသည် ကျောင်းမှဖွင့်မထားသောလုပ်ဆောင်ချက်များ ပါဝင်နိုင်သည်။',
