  'admin.shareInviteMessage': '{orgName}- Mind Thinking သင်ကြားမှုနှင့် သုတေသန ကိုယ်စားလှယ် ပလက်ဖောင်းကို တွေ့ကြုံခံစားရန် ကြိုဆိုပါတယ်။ \nBeijing Normal University ၏ တွေးခေါ်မှု လေ့ကျင့်ရေးစင်တာသည် သုတေသနနှင့် ဖွံ့ဖြိုးတိုးတက်ရေးကို လမ်းညွှန်ပြသထားပြီး တွေးခေါ်မှုဆိုင်ရာ ဖွံ့ဖြိုးတိုးတက်ရေး မဟာမိတ်ကျောင်းပေါင်း တစ်ရာကျော်ဖြင့် ပူးပေါင်းတည်ဆောက်ထားသည်။ AI ခေတ်တွင် သင်၏ စဉ်းစားတွေးခေါ်နိုင်စွမ်းကို မြှင့်တင်ရန်အတွက် သင်၏လုပ်ဖော်ကိုင်ဖက်များနှင့် ပူးပေါင်းလေ့လာရန် ဖိတ်ခေါ်အပ်ပါသည်။\nနည်းလမ်း- ကွန်ပျူတာ သို့မဟုတ် မိုဘိုင်းလ်ဖုန်းကို ဖွင့်ပါ၊ မိုဘိုင်းလ်ဖုန်းနံပါတ် + ဖိတ်ကြားချက်ကုဒ်ကို အသုံးပြု၍ ပထမဆုံးအကြိမ် မှတ်ပုံတင်ခြင်းကို အပြီးသတ်ရန်၊ ထို့နောက် မိုဘိုင်းလ်ဖုန်း အတည်ပြုကုဒ်ဖြင့် ဝင်ရောက်ပါ။\nဝဘ်ဆိုဒ်- {siteUrl}\nအဖွဲ့အစည်းအလိုက် ဖိတ်ကြားချက် ကုဒ်- {code}',
